input.command:
ip tunnel add gre1 mode gre local 100.64.0.1 remote 100.64.0.2 ttl 255
ip addr add 172.16.0.1/30 dev gre1
ip link set gre1 up
ip route add 10.2.0.0/16 dev gre1
cat > /etc/swanctl/conf.d/gre.conf <<'EOF'
connections {
  gre {
    local_addrs = 100.64.0.1
    remote_addrs = 100.64.0.2
    local { auth = psk }
    remote { auth = psk }
    children {
      gre-esp {
        mode = transport
        local_ts = 100.64.0.1[gre]
        remote_ts = 100.64.0.2[gre]
        start_action = trap
        esp_proposals = aes256-sha256-modp2048
      }
    }
    version = 2
    proposals = aes256-sha256-modp2048
  }
}
secrets { ike-gre { secret = "S3cret!" } }
EOF
chmod 600 /etc/swanctl/conf.d/gre.conf
(/usr/lib/ipsec/charon >/var/log/charon.log 2>&1 &) ; sleep 3; swanctl --load-all; swanctl --list-sas; ip route

